.huw-puppet-workshop .huw-puppet-presets button{font-size:11px;padding:5px}
.huw-puppet-workshop .huw-puppet-file{display:flex;flex-direction:column;gap:5px;padding:7px;border:1px dashed #67859d;border-radius:5px;cursor:pointer;font-size:11px}
.huw-puppet-workshop .huw-puppet-file input{max-width:100%;font-size:10px}
.huw-puppet-workshop .huw-puppet-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 11px;background:#1a293d;border-top:1px solid #485c73;font-size:10px;color:#a8c7d4;min-height:35px}
.huw-puppet-workshop .huw-puppet-library-toggle{display:flex;align-items:center;gap:5px;color:#e3effa;white-space:nowrap}
