 .huw-puppet-workshop .huw-puppet-appbar button{padding:4px;font-size:10px}
}

/* Fyrtøjet demo: dedicated SFX and compact scene blocks */
.huw-musical-sfx-key{border-radius:50%;background:#d2a16c!important;color:#342033!important;rotate:0deg!important;font-size:10px!important;min-width:16px;max-width:20px;line-height:14px;}
.huw-musical-scene-clip{box-sizing:border-box;position:absolute;top:6px;height:23px;min-width:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:1px solid #48726c;background:#336d65;color:#f4fbf6;border-radius:3px;padding:2px 4px;font-size:10px;text-align:left;cursor:pointer;}
.huw-musical-scene-clip:nth-child(3n+1){background:#3b6775;}

/* Musical score as a two-way navigation surface for the master playhead. */
.huw-musical-score-page .huw-musical-score-note-target,
.huw-musical-score-page .abcjs-chord,
.huw-musical-score-page .abcjs-chord-text{cursor:pointer;}
.huw-musical--workspace .huw-musical-track[data-track-id="music:A"],
.huw-musical--workspace .huw-musical-track[data-track-id="music:B"]{min-height:43px;}
.huw-musical--workspace .huw-musical-track[data-track-id="music:B"] .huw-musical-lane-title{border-left-color:#bb97e4;}
.huw-musical--workspace .huw-musical-song-clip{touch-action:none;}

/* Direct manipulation (puppet and camera), editor-only SVG overlay. */
.huw-musical-transform-overlay{touch-action:none;user-select:none}
.huw-musical-transform-outline{fill:rgba(255,210,95,.05);stroke:#ffe29c;stroke-width:2.2;stroke-dasharray:8 5;cursor:move;vector-effect:non-scaling-stroke;pointer-events:all}
.huw-musical-transform-corner{fill:#fff8cf;stroke:#b16a27;stroke-width:2.3;vector-effect:non-scaling-stroke;cursor:nwse-resize;pointer-events:all}
.huw-musical-transform-rotate{fill:#8cddf5;stroke:#195779;stroke-width:2.3;vector-effect:non-scaling-stroke;cursor:crosshair;pointer-events:all}
.huw-musical-transform-skew{fill:#eb99ee;stroke:#694187;stroke-width:2;vector-effect:non-scaling-stroke;cursor:alias;pointer-events:all}
.huw-musical-transform-guide{stroke:#8cddf5;stroke-width:1.8;stroke-dasharray:3 4;pointer-events:none;vector-effect:non-scaling-stroke}
.huw-musical-transform-label{fill:#ffe2a6;paint-order:stroke;stroke:#121b2b;stroke-width:4;stroke-linejoin:round;font-size:13px;font-weight:700;pointer-events:none}
.huw-musical--workspace .huw-musical-transform-button[aria-pressed="true"]{background:#2a6884;border-color:#75c8e6;color:#fff}


/* Object-first selection: tapping the figure passes through the translucent
   bounding box, while handles and the dashed edge remain draggable. */
.huw-musical-transform-overlay[data-mode="figure"] .huw-musical-transform-outline{pointer-events:stroke}
.huw-musical--workspace .huw-musical-canvas svg{touch-action:none}
.huw-musical--workspace .huw-musical-canvas [data-cutout-id]{cursor:grab}
.huw-musical--workspace .huw-musical-canvas [data-cutout-id]:active{cursor:grabbing}
.huw-musical--workspace .huw-musical-transform-corner,.huw-musical--workspace .huw-musical-transform-rotate,.huw-musical--workspace .huw-musical-transform-skew{touch-action:none}

/* The timeline title is a second, touch-friendly stage selection surface.
   Double click / Enter marks the entire object, never just a limb. */
.huw-musical-select-object-title{cursor:pointer;touch-action:manipulation}
.huw-musical-select-object-title:hover{color:#e4f4ff;background:rgba(120,185,213,.14)}
.huw-musical-select-object-title:focus-visible{outline:2px solid #ffd37e;outline-offset:-2px}
.huw-musical-track.is-selected>.huw-musical-lane-title{box-shadow:inset 3px 0 0 #ffd37e}

/* One accessible object chooser rather than one timeline row per prop. */
.huw-musical-object-picker{position:relative;top:5px;margin-left:9px;min-height:25px;width:calc(100% - 18px);max-width:360px;color:#e9f4ff;background:#263f53;border:1px solid #55738c;border-radius:5px;font-size:12px;padding:3px 5px}

/* Subtitles are camera-fixed HUD, not transformed CutOut scene objects. */
.huw-musical-canvas{position:relative;}
.huw-musical-canvas>.huw-musical-caption-overlay{
 position:absolute;inset:0;z-index:22;display:flex;align-items:center;
 justify-content:flex-end;flex-direction:column;pointer-events:none;
 box-sizing:border-box;padding:0 5% 5%;text-align:center;
 color:#fff8ec;font-family:system-ui,-apple-system,sans-serif;
}
.huw-musical-caption-overlay .huw-musical-caption-line{
 max-width:98%;padding:.32em .68em;border-radius:6px;
 background:rgba(9,12,18,.66);font-size:clamp(12px,1.45vw,20px);
 line-height:1.45;font-weight:650;text-shadow:0 1px 3px #080a0e;
}
.huw-musical-caption-overlay .huw-musical-caption-cue{
 max-width:98%;margin-bottom:.4em;padding:.14em .55em;border-radius:5px;
 background:rgba(8,12,20,.48);font-size:clamp(10px,1.15vw,15px);
 color:#ffdfa2;font-weight:600;
}
.huw-musical-caption-overlay [hidden]{display:none!important;}

/* Musical inspector 0.9.2 — readable, context-specific, safely scrollable.
   All properties must fit on an iPad even in focus mode. */
.huw-musical--workspace .huw-musical-inspector-drawer{
 min-width:0;max-width:100%;overflow-x:hidden;overflow-y:auto;
 scrollbar-width:thin;scrollbar-color:#738ca5 #203247;
 overscroll-behavior-y:contain;
}
.huw-musical--workspace .huw-musical-inspector{
 display:block!important;min-width:0;width:100%;max-width:100%;
 padding:12px 13px 24px;overflow-wrap:anywhere;
}
.huw-musical--workspace .huw-musical-inspector>*{max-width:100%;margin:0 0 11px;}
.huw-musical--workspace .huw-musical-inspector>strong{display:block;font-size:13px;line-height:1.4;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-property{
