}
.huw-musical--workspace .huw-musical-inspector .huw-musical-mute{flex-direction:row;align-items:center;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-mute input{width:auto;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-key-actions{display:flex;gap:6px;flex-wrap:wrap;}
.huw-musical--workspace .huw-musical-inspector-type{
