}
.huw-musical--workspace .huw-musical-inspector-heading strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
@media(min-width:1350px){
 .huw-musical--workspace.huw-musical--inspector-open .huw-musical-workbench{
  grid-template-columns:minmax(0,1fr) minmax(280px,330px);
 }
 .huw-musical--workspace.huw-musical--inspector-open .huw-musical-inspector-drawer{
  width:auto;min-width:0;
 }
