 background:#1c2e42;border-bottom:1px solid #4b657f;}
.huw-script-common>strong{margin-right:10px;font-size:12px;}
.huw-script-field{display:flex;flex-direction:column;gap:4px;font-size:11px;color:#c2d5e5;min-width:0;}
.huw-script-common .huw-script-field{width:125px;}
.huw-script-common input[type=range]{width:100%;height:20px;accent-color:#5aaac0;}
.huw-script-caption-preview{flex:1;min-width:170px;display:flex;flex-direction:column;align-items:center;
 justify-content:flex-end;min-height:45px;background:#253346;border:1px solid #364d65;border-radius:5px;overflow:hidden;}
