 // Prefer A for consecutive clips; B only when A is occupied by an overlap.
 var placed=[];
 clips.slice().sort(function(a,b){return a.start-b.start;}).forEach(function(c){
  var clash=function(lane){return placed.some(function(p){return p.lane===lane&&overlap(p,c)>.005;});};
  if(c.lane!=="A"&&c.lane!=="B")c.lane=!clash("A")?"A":"B";
  placed.push(c);
